async function (triggerType, triggerData, reactorToken, item, activationName, api)
{
    const targets = triggerData.targets?.map(t => t.target).filter(Boolean) || [];
    for (const target of targets)
    {
        const result = await api.executeStatRoll(
            target.actor, 
            "HULL", 
            "Hull Save - Impaler Nailgun (> " + reactorToken.actor.system.save + ")", 
            reactorToken.actor.system.save);
        if (!result.passed) {
            api.applyEffectsToTokens({
                tokens: [target],
                effectNames: ["immobilized"],
                duration: {label: "end", turns: 1},
            });
        }
    }
}
